insert into eldervale_private.realm_catalog(id,data) select r->>0,r->1 from jsonb_array_elements($j$[["item:custom_qa_frost_verse",{"name":"Frost-verse stone","description":"A palm-sized slate scratched with an old shepherd’s song. The lines melt and refreeze as you read them.","icon":"scroll","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_shepherds_crook",{"name":"Pale Shepherd’s crook","description":"A crook of blue ice that will not melt. Marshal Vossberg will want to see it.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}],["item:custom_qa_wardstone",{"name":"Wardstone of Hearthmoor","description":"A warm grey stone on a cord, cut from the great beacon. Rub it to return to Hearthmoor.","icon":"gem","custom":true,"category":"Quest items","buy":0,"sell":0,"unique":true,"tradeable":false,"untradeable":true,"questItem":true,"keepOnDeath":true,"shopless":true}]]$j$::jsonb) r
