-- People, monsters and shortcuts of the arc (fixed ids; the entity trigger fills realm_actors / realm_objects).
select eldervale_private.quest_arc_entities($j$[{"id":"a3c0a000-0002-4000-8000-000000000001","data":{"kind":"npc","name":"Marshal Ingrid Vossberg","role":"guard","weapon":"twohand","attackType":"slash","color":5466234,"level":35,"hp":180,"damage":19,"attackSpeed":3.2,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Winterwatch holds because the beacons burn.\nWhen they go dark, everything north of here gets ideas.","template":"knight","x":214,"z":-236,"yaw":90,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:vossberg"}},{"id":"a3c0a000-0002-4000-8000-000000000002","data":{"kind":"npc","name":"Pell Ashby the Beacon-Keeper","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Eastwatch beacon, keeper on duty. Awake on duty. Mostly.","template":"villager","x":262,"z":-214,"yaw":180,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:pell"}},{"id":"a3c0a000-0002-4000-8000-000000000003","data":{"kind":"npc","name":"Mother Rusk","role":"healer","weapon":null,"attackType":"magic","color":14735023,"level":5,"hp":45,"damage":5,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Salves, tinctures, and the truth, all bitter.\nSit by the fire. Not too close.","template":"healer","x":238,"z":-228,"yaw":180,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:rusk"}},{"id":"a3c0a000-0002-4000-8000-000000000004","data":{"kind":"npc","name":"Torvald the Trapper","role":"ranger","weapon":"shortsword","attackType":"arrow","color":5532994,"level":12,"hp":70,"damage":8,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Frostfang pass. Wolves on the left, wolves on the right, wolves in the middle.","template":"ranger","x":100,"z":-248,"yaw":90,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:torvald"}},{"id":"a3c0a000-0002-4000-8000-000000000005","data":{"kind":"npc","name":"Reeve Ottilie Marsh","role":"farmer","weapon":"axe","attackType":"slash","color":10189901,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Hearthmoor was a village once. It will be again, if I have to carry every stone.","template":"farmer","x":258,"z":-298,"yaw":0,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:ottilie"}},{"id":"a3c0a000-0002-4000-8000-000000000006","data":{"kind":"npc","name":"Hask the Troll-Tongue","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"I speak Troll, badly. They speak Common, worse. We manage.","template":"mage","x":285,"z":-315,"yaw":-90,"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:hask"}},{"id":"a3c0a000-0002-4000-9000-000000000001","data":{"kind":"monster","name":"Snuff imp","species":"imp","attackType":"magic","level":6,"hp":85,"damage":1,"attackSpeed":2.8,"roam":2,"respawn":60,"attackable":true,"hostile":false,"scale":0.55,"template":"imp","x":268,"z":-210,"yaw":0,"maxHit":17,"attackLevel":4,"strengthLevel":4,"defenceLevel":4,"magicLevel":7,"attackBonus":2,"defenceBonuses":{"stab":2,"slash":2,"crush":2,"magic":3,"ranged":1},"xpReward":37,"goldReward":10,"tint":9083560,"eyes":10148095,"breath":10216042,"examine":"It eats flames. Small ones. It is working up to big ones.","loot":[{"item":"ashes","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:imp"}},{"id":"a3c0a000-0002-4000-9000-000000000002","data":{"kind":"monster","name":"Starving frostfang","species":"wolf","attackType":"bite","level":22,"hp":230,"damage":3,"attackSpeed":2,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1.12,"template":"wolf","x":130,"z":-258,"yaw":0,"maxHit":36,"attackLevel":22,"strengthLevel":18,"defenceLevel":15,"magicLevel":7,"attackBonus":7,"defenceBonuses":{"stab":5,"slash":5,"crush":6,"magic":5,"ranged":6},"xpReward":257,"goldReward":45,"tint":14673642,"eyes":8378111,"examine":"Ribs like a xylophone, teeth like knives.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:wolf1"}},{"id":"a3c0a000-0002-4000-9000-000000000003","data":{"kind":"monster","name":"Starving frostfang","species":"wolf","attackType":"bite","level":22,"hp":230,"damage":3,"attackSpeed":2,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1.12,"template":"wolf","x":136,"z":-252,"yaw":0,"maxHit":36,"attackLevel":22,"strengthLevel":18,"defenceLevel":15,"magicLevel":7,"attackBonus":7,"defenceBonuses":{"stab":5,"slash":5,"crush":6,"magic":5,"ranged":6},"xpReward":257,"goldReward":45,"tint":14673642,"eyes":8378111,"examine":"Ribs like a xylophone, teeth like knives.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:wolf2"}},{"id":"a3c0a000-0002-4000-9000-000000000004","data":{"kind":"monster","name":"Starving frostfang","species":"wolf","attackType":"bite","level":22,"hp":230,"damage":3,"attackSpeed":2,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1.12,"template":"wolf","x":128,"z":-246,"yaw":0,"maxHit":36,"attackLevel":22,"strengthLevel":18,"defenceLevel":15,"magicLevel":7,"attackBonus":7,"defenceBonuses":{"stab":5,"slash":5,"crush":6,"magic":5,"ranged":6},"xpReward":257,"goldReward":45,"tint":14673642,"eyes":8378111,"examine":"Ribs like a xylophone, teeth like knives.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","bluepr