eLevel":60,"magicLevel":25,"attackBonus":16,"defenceBonuses":{"stab":21,"slash":21,"crush":16,"magic":14,"ranged":22},"xpReward":1075,"goldReward":138,"tint":12575730,"eyes":8378111,"spikes":true,"accent":15333119,"examine":"A troll frozen in mid-stride and made to walk anyway.","loot":[{"item":"heftyBones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:thrall2"}},{"id":"a3c0a000-0002-4000-9000-000000000008","data":{"kind":"monster","name":"The Pale Shepherd","species":"wraith","attackType":"magic","level":90,"hp":2690,"damage":15,"attackSpeed":3.6,"roam":1,"respawn":90,"attackable":true,"hostile":true,"scale":2.2,"template":"wraith","x":2268,"z":3000,"yaw":0,"maxHit":183,"attackLevel":92,"strengthLevel":87,"defenceLevel":83,"magicLevel":97,"attackBonus":42,"defenceBonuses":{"stab":36,"slash":36,"crush":36,"magic":18,"ranged":36},"xpReward":6030,"goldReward":743,"tint":15267071,"eyes":10479871,"examine":"Tall as a pine, thin as frost. It walks the winter down the mountain like a flock.","loot":[{"item":"custom_qa_shepherds_crook","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:shepherd","aura":12578815,"crown":true}},{"id":"a3c0a000-0002-4000-9000-000000000009","data":{"kind":"monster","name":"The Pale Shepherd, Unbound","species":"wraith","attackType":"magic","level":110,"hp":4080,"damage":19,"attackSpeed":3.4,"roam":1,"respawn":300,"attackable":true,"hostile":true,"scale":2.6,"template":"wraith","x":2226,"z":3400,"yaw":0,"maxHit":241,"attackLevel":113,"strengthLevel":107,"defenceLevel":101,"magicLevel":119,"attackBonus":50,"defenceBonuses":{"stab":43,"slash":43,"crush":43,"magic":22,"ranged":43},"xpReward":8910,"goldReward":1073,"tint":13954303,"eyes":16777215,"examine":"The Shepherd, with nothing left to herd but you. Harder mode.","loot":[{"item":"yewLogs","min":10,"max":25,"chance":1,"always":true},{"item":"runiteOre","min":1,"max":2,"chance":0.35},{"item":"cutGem","min":1,"max":3,"chance":0.5}],"behavior":"wander","questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:unbound","aura":10476799,"crown":true}},{"id":"a3c0a000-0002-4000-a000-000000000001","data":{"kind":"object","name":"Rimeback ice-stair","scale":1,"level":1,"hp":1,"damage":0,"attackSpeed":2.4,"roam":0,"respawn":0,"attackable":false,"hostile":false,"template":"wall_climb","x":272.5,"z":-309,"yaw":124,"length":10.8,"agility":{"id":"rimeback_stair","level":35,"xp":30,"fail":0.2,"failDamage":40,"ticks":4,"margin":20,"ends":[[268,-306],[277,-312]],"requires":{"unlock":"shortcut.frontier-ice-stair"}},"questArc":"frontier","blueprint":"quest-arcs-v1","blueprintKey":"frontier:rimeback_stair"}}]$j$::jsonb);

-- Quests (validated by quest_v2_check; edit them later in the Game console › Quests).
select eldervale_private.quest_arc_put('a3c0b000-0002-4000-8000-000000000001',$q${"chain":"arc-frontier","order":1,"published":true,"objectives":[],"key":"arc-frontier-1","name":"Ashes on the Wardfires","questPoints":1,"difficulty":"Novice","length":"Short","giver":"a3c0a000-0002-4000-8000-000000000001","icon":"oakLogs","description":"The wardfire beacons that ring Winterwatch have gone dark one by one. Marshal Vossberg wants the Eastwatch beacon burning before nightfall.","dialogue":{"offer":[{"who":"npc","text":"You. You look like you can carry wood and swing a stick. Both skills are in short supply."},{"who":"npc","text":"The wardfires keep the north honest. Three have gone dark this month and nobody can tell me why."},{"who":"npc","text":"Get up to Eastwatch, find young Pell, and get that beacon lit. If he is asleep, wake him. Firmly."}],"progress":[{"who":"npc","text":"Is Eastwatch burning? I can see it from here, so: no."}],"complete":[{"who":"npc","text":"Trolls? Stealing firewood? Trolls do not steal firewood. Trolls do not feel the cold."},{"who":"npc","text":"...Unless something has made them. I do not like the shape of that thought. Here, for your trouble."}]},"stages":[{"id":"pell","journal":"Marshal Ingrid Vossberg asked me to relight the Eastwatch wardfire, on the hill east of Winterwatch. Its keeper is a young man called Pell Ashby.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000002","amount":1,"label":"Find Pell Ashby at the Eastwatch beacon","dialogue":[{"who":"npc","text":"I was not asleep! I was resting my eyes in a lookout posture."},{"who":"npc","text":"Something keeps snuffing the fire. Little grey thing, all mouth. It ate my tinderbox. My second tinderbox."}]}]},{"id":"imp","journal":"Pell says a little grey creature keeps eating the beacon’s flames, and his tinderboxes. I should get rid of it before I try to light anything.","onEnter":{"cutscene":"imp"},"objectives":[{"type":"kill","target":"a3c0a000-0002-4000-9000-000000000001","amount":1,"label":"Get rid of the snuff imp"}]},{"id":"timber","journal":"The snuff imp is gone, but so is the beacon’s woodpile. I need to chop some logs and get a good fire going to show Pell I know how.","objectives":[{"type":"event","event":"woodcut","amount":3,"label":"Chop logs for the beacon"},{"type":"xp","skill":"firemaking","amount":40,"label":"Light a fire (Firemaking XP)"}]},{"id":"tracks","journal":"With the beacon lit again, Pell showed me deep tracks in the snow leading east from the empty woodpile. Somebody big carried the firewood away. I should follow the tracks a little way.","objectives":[{"type":"visit","x":274,"z":-222,"radius":4,"amount":1,"label":"Follow the tracks east from the beacon"}]},{"id":"rusk","journal":"The tracks were troll tracks, and they carried the wood away carefully, like something precious. Mother Rusk at the Winterwatch Lodge knows more about trolls than anyone; I should ask her before I report to the Marshal.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000003","amount":1,"label":"Ask Mother Rusk about the troll tracks","dialogue":[{"who":"npc","text":"Trolls carrying firewood? Hah. And next the fish will take up knitting."},{"who":"npc","text":"...You are serious. Trolls are made of cold, child. A troll by a fire is a troll that is dying, or frightened of something colder."}]}]}],"cutscenes":{"imp":{"name":"The snuff imp","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"Eastwatch beacon","subtitle":"East of Winterwatch","ms":2400},{"say":{"who":"npc","name":"Pell Ashby","text":"There! The grey one! It is looking at the fire like I look at pie."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"lit":{"name":"Eastwatch burns","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"The first wardfire","subtitle":"Winterwatch","ms":2400},{"say":{"who":"npc","name":"Marshal Ingrid Vossberg","text":"One beacon. One. And it took a stranger to light it. Fine. It is a start."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"lit"},"journalDone":"I drove off a snuff imp and relit the Eastwatch wardfire. The missing firewood was carried off by trolls, which Mother Rusk says only happens when trolls are frightened of something colder than themselves.","gold":150,"xp":{"firemaking":1500,"woodcutting":1000},"lamps":[{"perLevel":10,"minLevel":5,"label":"Wardfire lamp"}],"unlocks":[{"type":"flag","id":"frontier.eastwatch_lit","label":"The Eastwatch wardfire burns again"},{"type":"dialogue","id":"dialogue.frontier-pell-1","label":"Pell stays awake","npc":"a3c0a000-0002-4000-8000-000000000002","lines":[{"who":"npc","text":"Fire’s burning, eyes are open. I have taken up humming. It helps. The wolves hate it."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0002-4000-8000-000000000002',$q${"chain":"arc-frontier","order":2,"published":true,"objectives":[],"key":"arc-frontier-2","name":"The Hungry Pass","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0002-4000-8000-000000000005","icon":"trout","requirements":{"quests":["arc-frontier-1"],"skills":{"fishing":{"level":20,"boostable":false},"cooking":{"level":20,"boostable":false}}},"description":"The grain promised from Birchford never came, and the ruined hamlet of Hearthmoor is going hungry. Reeve Ottilie Marsh needs food brought over the Frostfang pass.","dialogue":{"offer":[{"who":"npc","text":"Hearthmoor burned two winters ago. Twelve families came back anyway. Stubborn, like me."},{"who":"npc","text":"Birchford promised us grain. Royal writs, royal seals. Nothing came. Not a sack."},{"who":"npc","text":"Torvald the trapper runs a sled over the Frostfang pass. He needs fish for the cart and a strong arm for the wolves. Will you?"}],"progress":[{"who":"npc","text":"The children are eating snow and pretending it is porridge. They are very good at pretending."}],"complete":[{"who":"npc","text":"Bread! And fish! Torvald, you old goat, you came through."},{"who":"npc","text":"Thank you. Truly. Hearthmoor will remember who fed it in the long winter."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"fed_trolls":true},"lines":[{"who":"npc","text":"Bread and fish, and less than there might have been. You fed the trolls, I hear."},{"who":"npc","text":"...My grandmother would have spat. I think she would have been wrong. Thank you."}]}],"stages":[{"id":"trapper","journal":"Reeve Ottilie Marsh of Hearthmoor told me the grain promised from Birchford never arrived. Torvald the trapper, at the west end of the Frostfang pass, runs a sled over the mountains.","npc":"a3c0a000-0002-4000-8000-000000000004","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000004","amount":1,"label":"Find Torvald the Trapper at the Frostfang pass","dialogue":[{"who":"npc","text":"Hearthmoor again? My traps are empty, my sled is empty, and my wife says my head is empty."},{"who":"npc","text":"Bring me fish and I will haul them. Cooked; raw fish freezes into a club up there."}]}]},{"id":"catch","journal":"Torvald will run his sled to Hearthmoor if I bring him four cooked trout. Raw fish freeze solid on the pass.","npc":"a3c0a000-0002-4000-8000-000000000004","objectives":[{"type":"collect","target":"trout","amount":4,"label":"Bring Torvald four cooked trout"}],"dialogue":{"advance":[{"who":"npc","text":"Good fish. Now walk ahead of the sled and keep your eyes on the treeline. The wolves are hungrier than we are."}]}},{"id":"ford","journal":"Torvald loaded the sled and asked me to walk ahead of him over the pass, starting with the frozen ford.","onEnter":{"cutscene":"sled"},"objectives":[{"type":"visit","x":132,"z":-252,"radius":6,"amount":1,"label":"Lead the sled to the frozen ford"}]},{"id":"wolves","journal":"At the frozen ford a pack of starving frostfang wolves came out of the trees for the sled.","objectives":[{"type":"event","event":"death","targets":["a3c0a000-0002-4000-9000-000000000002","a3c0a000-0002-4000-9000-000000000003","a3c0a000-0002-4000-9000-000000000004"],"amount":3,"label":"Drive off the starving frostfangs"}]},{"id":"scouts","journal":"Past the ford, near Hearthmoor, two young trolls were crouched in the snow, thin as rakes and shivering. Reeve Ottilie came out to meet the sled and saw them too.","npc":"a3c0a000-0002-4000-8000-000000000005","objectives":[{"type":"visit","x":240,"z":-292,"radius":5,"amount":1,"label":"Bring the sled past the troll scouts to Hearthmoor"}],"dialogue":{"choice":[{"who":"npc","text":"Trolls. At my gate. Burned my village, their kind did, or their cousins did."},{"who":"npc","text":"They look starving. So do we. It is your sled now as much as Torvald’s. You decide."}]},"choices":[{"id":"feed","label":"Leave a share of the fish for the trolls.","flags":{"fed_trolls":true},"dialogue":[{"who":"npc","text":"...Fine. Fine! But if they come back for seconds, you are the one telling them no."}]},{"id":"drive","label":"Drive the trolls off. Hearthmoor eats first.","flags":{"drove_trolls":true},"dialogue":[{"who":"npc","text":"Good. Hard, but good. They will not forget it, mind. Neither will I."}]}]},{"id":"bread","journal":"The sled is at Hearthmoor. Ottilie still needs three loaves of bread for the children before she will call the run a success.","objectives":[{"type":"collect","target":"bread","amount":3,"label":"Bring Reeve Ottilie three loaves of bread"}]}],"cutscenes":{"sled":{"name":"Over the pass","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"The Frostfang pass","subtitle":"Between Winterwatch and the west","ms":2400},{"say":{"who":"npc","name":"Torvald the Trapper","text":"Walk ahead, stay on the packed snow, and if you hear howling, do not howl back. It encourages them."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"fed":{"name":"Hearthmoor eats","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"Hearthmoor eats","subtitle":"The ruins of Hearthmoor","ms":2400},{"say":{"who":"npc","name":"Reeve Ottilie Marsh","text":"Twelve families, one sled, one stranger. Not bad for a winter that was meant to finish us."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"fed"},"journalDone":"I helped Torvald run a sled of cooked trout over the Frostfang pass to Hearthmoor, driving off a starving wolf pack on the way, and brought bread for the children.","journalVariants":[{"ifFlags":{"fed_trolls":true},"text":"I left a share of the food for two starving young trolls at Hearthmoor’s gate."},{"ifFlags":{"drove_trolls":true},"text":"I drove two starving young trolls away from Hearthmoor’s gate."}],"gold":400,"xp":{"fishing":6000,"cooking":5000,"strength":3000},"lamps":[{"perLevel":10,"minLevel":10,"label":"Sled-runner’s lamp"}],"unlocks":[{"type":"flag","id":"frontier.hearthmoor_fed","label":"Hearthmoor survives the winter"},{"type":"dialogue","id":"dialogue.frontier-torvald-2","label":"Torvald’s sled runs again","npc":"a3c0a000-0002-4000-8000-000000000004","lines":[{"who":"npc","text":"Two runs a week to Hearthmoor now. The wolves have started waiting politely by the ford. I do not trust it."}]},{"type":"dialogue","id":"dialogue.frontier-ottilie-fed","label":"Ottilie remembers the trolls","npc":"a3c0a000-0002-4000-8000-000000000005","ifFlags":{"fed_trolls":true},"lines":[{"who":"npc","text":"Those two young trolls left a pile of firewood by my gate last night. Neatly stacked. I am not crying, it is the cold."}]},{"type":"dialogue","id":"dialogue.frontier-ottilie-drove","label":"Ottilie keeps watch","npc":"a3c0a000-0002-4000-8000-000000000005","ifFlags":{"drove_trolls":true},"lines":[{"who":"npc","text":"No trolls at the gate since. I sleep with a poker, all the same."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0002-4000-8000-000000000003',$q${"chain":"arc-frontier","order":3,"published":true,"objectives":[],"key":"arc-frontier-3","name":"Under the Rimeback","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0002-4000-8000-000000000003","icon":"custom_qa_frost_verse","requirements":{"quests":["arc-frontier-2","arc-forge-2"],"skills":{"agility":{"level":25,"boostable":false},"herblore":{"level":15,"boostable":false}}},"description":"Mother Rusk believes the trolls are fleeing something on the peaks. She wants someone to go up the Rimeback and ask them. Politely.","dialogue":{"offer":[{"who":"npc","text":"Trolls do not run from men. They do not run from wolves. They run from one thing in all my grandmother’s stories."},{"who":"npc","text":"The Pale Shepherd. A cold that walks, and herds the winter down the mountain like sheep."},{"who":"npc","text":"There is a hermit in the Rimeback foothills, Hask, who speaks Troll. Badly. Go and ask him what the trolls are running from."}],"progress":[{"who":"npc","text":"Well? Did Hask make sense? He rarely does before noon."}],"complete":[{"who":"npc","text":"The song of the hearth. Of course. My grandmother sang it to frighten the frost out of the windows."},{"who":"npc","text":"Take this, and keep that stone. We will need its song again, I think."}]},"stages":[{"id":"hask","journal":"Mother Rusk fears the trolls are fleeing the Pale Shepherd, a walking cold from her grandmother’s stories. Hask the Troll-Tongue, a hermit in the Rimeback foothills south-east of Hearthmoor, may know.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000006","amount":1,"label":"Ask Hask the Troll-Tongue what the trolls fear","dialogue":[{"who":"npc","text":"They say: tall-cold-walker. They say: it takes the young ones and makes them stop. Stop moving. Stop being warm."},{"who":"npc","text":"There is an old cairn up the slope where the shepherds sang to keep it away. The trolls will not go near it now. Something guards it."}]}]},{"id":"cairn","journal":"Hask says the trolls call it the tall-cold-walker, and that it freezes their young. An old shepherds’ cairn up the slope from his camp was where people once sang to keep it away.","objectives":[{"type":"visit","x":290,"z":-303,"radius":4,"amount":1,"label":"Climb to the old shepherds’ cairn"}]},{"id":"wight","journal":"The cairn is guarded by the ghost of a shepherd, rimed with frost and still counting its flock.","onEnter":{"cutscene":"cairn"},"objectives":[{"type":"kill","target":"a3c0a000-0002-4000-9000-000000000005","amount":1,"label":"Lay the cairn-frost wight to rest"},{"type":"have","target":"custom_qa_frost_verse","amount":1,"label":"Pick up the frost-verse stone"}]},{"id":"salve","journal":"The wight left a slate scratched with an old song. Mother Rusk can read the old shepherds’ marks, and she will want herbs to brew a thaw-salve while she does.","npc":"a3c0a000-0002-4000-8000-000000000003","objectives":[{"type":"collect","target":"cleanHerb","amount":3,"label":"Bring Mother Rusk three clean herbs"},{"type":"have","target":"custom_qa_frost_verse","amount":1,"label":"Show her the frost-verse stone"}],"dialogue":{"advance":[{"who":"npc","text":"Three songs on one stone. The shepherds sang one of them to drive the cold back. Which one, though?"},{"who":"npc","text":"“The hunt that runs before the snow. The hearth that waits behind the door. The flock that sleeps beneath the stars.” Think, child. What does the cold fear?"}]}},{"id":"riddle","journal":"The stone holds three shepherds’ songs: of the hunt that runs before the snow, of the hearth that waits behind the door, and of the flock that sleeps beneath the stars. Only one drove the cold back. Mother Rusk wants my answer.","npc":"a3c0a000-0002-4000-8000-000000000003","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000003","amount":1,"label":"Tell Mother Rusk which song drives back the cold"}],"dialogue":{"choice":[{"who":"npc","text":"Well? Which song?"}]},"choices":[{"id":"hearth","label":"The hearth that waits behind the door.","next":"warn","flags":{"knew_hearth":true},"dialogue":[{"who":"npc","text":"Yes. Warmth that waits for someone to come home. The cold cannot bear it."}]},{"id":"hunt","label":"The hunt that runs before the snow.","next":"think","dialogue":[{"who":"npc","text":"The hunt runs from the snow, child. That is a song for losing. Go and ask Hask what the trolls sing."}]},{"id":"flock","label":"The flock that sleeps beneath the stars.","next":"think","dialogue":[{"who":"npc","text":"A sleeping flock is what the Shepherd wants. Go and ask Hask what the trolls sing."}]}]},{"id":"think","journal":"My answer was wrong. Mother Rusk sent me back to Hask to ask what the trolls sing when they are frightened.","next":"riddle","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000006","amount":1,"label":"Ask Hask what the trolls sing","dialogue":[{"who":"npc","text":"Trolls sing about a cave with a fire in it and someone waiting. It is the saddest song they have. They have never had one."}]}]},{"id":"warn","journal":"The shepherds’ song is the song of the hearth. Mother Rusk says the Marshal must hear about the Pale Shepherd before it comes down to the valley.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000001","amount":1,"label":"Warn Marshal Vossberg about the Pale Shepherd","dialogue":[{"who":"npc","text":"A walking winter. Herding trolls. Wonderful. Any more good news? No? Then thank Rusk for me."}]}]}],"cutscenes":{"cairn":{"name":"The shepherds’ cairn","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000006","distance":5,"height":2.2,"angle":30}},{"title":"The shepherds’ cairn","subtitle":"The Rimeback foothills","ms":2400},{"say":{"who":"npc","name":"Hask the Troll-Tongue","text":"Careful. The trolls say the cairn counts you. If it reaches a number it likes, it keeps you."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000006","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"song":{"name":"The song of the hearth","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000003","distance":5,"height":2.2,"angle":30}},{"title":"The song of the hearth","subtitle":"The Winterwatch Lodge","ms":2400},{"say":{"who":"npc","name":"Mother Rusk","text":"Every window in this town has a candle in it on the longest night. Now you know why."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000003","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"song"},"journalDone":"Hask the Troll-Tongue told me the trolls flee the Pale Shepherd. At an old shepherds’ cairn I laid a frost-wight to rest and found a stone of songs; Mother Rusk and I worked out that the song of the hearth drives the cold back. Marshal Vossberg has been warned.","gold":500,"xp":{"herblore":6000,"agility":5000,"prayer":3000},"lamps":[{"perLevel":10,"minLevel":15,"label":"Hearth-song lamp"}],"unlocks":[{"type":"flag","id":"frontier.hearth_song","label":"Winterwatch remembers the song of the hearth"},{"type":"dialogue","id":"dialogue.frontier-hask-3","label":"Hask trusts you","npc":"a3c0a000-0002-4000-8000-000000000006","lines":[{"who":"npc","text":"The trolls call you warm-walker now. It is either a great honour or a recipe. Their grammar is unclear."}]}]}$q$::jsonb);

commit;
